import {
    SPECIFIC_ABILITY_SUPPRESS,
    SPECIFIC_ACTIVATION_FREQUENCY,
    SPECIFIC_EFFECTS,
    SPECIFIC_NAMES,
    TEXT,
} from "./const.js";

export function hasActivations(item) {
    return item.system.description.value.includes(`<p><strong>${TEXT.ACTIVATE_TEXT}`);
}

/**
 * Generates the Activation Items
 * @param {Item} item  Item to get Activations from
 * @returns {Item} An array of Activations
 */
export function generateActivations(item) {
    const description = item.system.description.value;
    const isRemaster = description.includes(`<p><strong>${TEXT.ACTIVATE_TEXT}—`);
    let result = description.split(`<p><strong>${TEXT.ACTIVATE_TEXT}`).slice(1) ?? [];
    result = result
        .filter((description, cnt) => isValidActivation(description, item?.slug, cnt))
        .map((descAction, num) => {
            const type = descAction.includes(`<span class="action-glyph">`)
                ? descAction.split(`<span class="action-glyph">`)[1]?.split(`</span>`)[0]
                : descAction.split(`<span class="action-glyph">`)[1]?.split(`<span class="pf2-icon">`)[0];
            const actionType = getActionInfo(type);
            const action = {
                img: item.img,
                type: "action",
                system: {
                    description: {
                        value: `<p><strong>${TEXT.ACTIVATE_TEXT}` + descAction.substring(descAction),
                    },
                    traits: {
                        value: [],
                    },
                    actions: {
                        value: actionType.cnt,
                    },
                    actionType: {
                        value: actionType.type,
                    },
                },
            };
            if (descAction.includes(`<strong>${TEXT.FREQUENCY_TEXT}</strong> `))
                action.system.frequency = getFrequency(
                    descAction.split(`<strong>${TEXT.FREQUENCY_TEXT}</strong> `)[1]?.split(`</p>`)[0]
                );
            if (isRemaster) {
                action.name = `${TEXT.ACTIVATION_TEXT}: ${descAction.split("</strong>")[0].replace("—", "")}`;
                const traitLine = `${descAction?.split("</p>")?.[0]}()`;
                action.system.traits.value = traitLine
                    .slice(traitLine.indexOf("(") + 1, traitLine.indexOf(")"))
                    .split(",")
                    .filter((t) => t.trim().length > 0);
            } else {
                const legacyName = SPECIFIC_NAMES?.[item?.slug]?.[num]
                    ? SPECIFIC_NAMES?.[item?.slug]?.[num]
                    : item.name;
                action.name = `${TEXT.ACTIVATION_TEXT}: ${legacyName}`;
                action.system.traits.value = getOldActionTraits(getOldActionTraitString(descAction));
            }
            action.system.slug = game.pf2e?.system?.sluggify(action.name);

            const effectUUID = (SPECIFIC_EFFECTS[item.system.slug] ||
                SPECIFIC_EFFECTS[game.pf2e?.system?.sluggify(item?.name)])?.[num];
            if (effectUUID) {
                action.system.selfEffect = { uuid: effectUUID };
            }

            const specificActivationFrequency = (SPECIFIC_ACTIVATION_FREQUENCY[item.system.slug] ||
                SPECIFIC_ACTIVATION_FREQUENCY[game.pf2e?.system?.sluggify(item?.name)])?.[num];
            if (specificActivationFrequency) {
                action.system.frequency = specificActivationFrequency;
            }

            action.system.traits.value.push("activation");
            return action;
        });
    return result;
}

function getActionInfo(type) {
    switch (type?.toLowerCase()) {
        case `1`:
        case `a`:
            return { type: `action`, cnt: 1 };
        case `2`:
        case `d`:
            return { type: `action`, cnt: 2 };
        case `3`:
        case `t`:
            return { type: `action`, cnt: 3 };
        case `r`:
            return { type: `reaction`, cnt: null };
        case `f`:
            return { type: `free`, cnt: null };
        default:
            return { type: `passive`, cnt: null };
    }
}

function getOldActionTraitString(desc) {
    let str = desc.split("</p>")[0];
    if (str.includes(`<span class="action-glyph">`) || str.includes(`<span class="pf2-icon">`)) {
        str = str.split(`</span>`)[1].trim();
    } else {
        str = str.toLowerCase();
        str = str.substring(
            Math.min(
                Math.max(str.indexOf(`${TEXT.COMMAND_TEXT}`), 9999),
                Math.max(str.indexOf(`${TEXT.ENVISION_TEXT}`), 9999),
                Math.max(str.indexOf(`${TEXT.INTERACT_TEXT}`), 9999)
            )
        );
    }
    return str.trim();
}

function getOldActionTraits(string) {
    let traits = [];

    // Extract traits enclosed within parentheses
    const parenthesizedTraits = string.match(/\(([^)]+)\)/);
    if (parenthesizedTraits) {
        traits = parenthesizedTraits[1].split(",").map((t) => t.trim());
        string = string.split("(")[0].trim();
    }

    // Split remaining traits by comma and concatenate with existing traits
    string.split(",").forEach((trait) => {
        traits = traits.concat(getNewTraits(trait.trim()));
    });

    // Remove duplicates and return unique traits
    return [...new Set(traits)];
}

function getNewTraits(activationOldTrait) {
    switch (activationOldTrait) {
        case `${TEXT.COMMAND_TEXT}`:
            return [`auditory`, `concentrate`];
        case `${TEXT.ENVISION_TEXT}`:
            return [`concentrate`];
        case `${TEXT.INTERACT_TEXT}`:
            return [`manipulate`];
        default:
            return [activationOldTrait];
    }
}

function getFrequency(str) {
    const [amt, unit] = [
        str.split(" ")[0],
        str
            .substring(str.split(" ")[0].length + 1)
            .replace(TEXT.PER, "")
            .trim(),
    ];
    const re = {
        max: 1,
        per: "day",
    };
    switch (amt.toLowerCase()) {
        case TEXT.COUNT.once:
            re.max = 1;
            break;
        case TEXT.COUNT.twice:
            re.max = 2;
            break;
        case TEXT.COUNT.threeTimes:
            re.max = 3;
            break;
        default:
            if (!isNaN(amt)) re.max = parseInt(amt);
    }
    switch (unit.toLowerCase()) {
        case `${TEXT.TIME.turn}`:
            re.per = `turn`;
            break;
        case `${TEXT.TIME.round}`:
            re.per = `round`;
            break;
        case `${TEXT.TIME.minute}`:
            re.per = `PT1M`;
            break;
        case `${TEXT.TIME["ten-minutes"]}`:
            re.per = `PT10M`;
            break;
        case `${TEXT.TIME.hour}`:
            re.per = `PT1H`;
            break;
        case `${TEXT.TIME["twenty-four-hours"]}`:
            re.per = `PT24H`;
            break;
        case `${TEXT.TIME.day}`:
            re.per = `day`;
            break;
        case `${TEXT.TIME.week}`:
            re.per = `P1W`;
            break;
        case `${TEXT.TIME.month}`:
            re.per = `P1M`;
            break;
        case `${TEXT.TIME.year}`:
            re.per = `P1Y`;
            break;
        default:
    }
    return re;
}

function isValidActivation(desc, slug, cnt) {
    return !TEXT.INVALID_ACTIVATIONS.some((regex) => regex.test(desc)) && !SPECIFIC_ABILITY_SUPPRESS?.[slug]?.[cnt];
}

sources.onCreate:
// Import groups
import { setModuleFlag } from "./misc.js";
import { TEXT, MODULE_ID } from "./const.js";

/**
 * Augments an action with item information
 * @param {object} action The action to augment
 * @param {object} item The item granting the action
 * @returns {object} The augmented action
 */
export function augmentAction(action, item) {
    let resultAction = { ...action };
    // Set module flag indicating the item granting the action
    resultAction = setModuleFlag(resultAction, "grantedBy", item.toObject());

    // Concatenate item information to action description
    resultAction.system.description.value = `<p>${TEXT.GRANTED_BY_TEXT} ${item.link}</p>`.concat(
        action.system.description.value
    );
    if (item.system.traits.value.includes("invested")) {
        resultAction.system.traits.value = [...resultAction.system.traits.value, "invested"];
    }

    //Update Icons
    if (game.settings.get(MODULE_ID, "action-type-icon")) resultAction.img = getActionImage(action);

    return resultAction;
}

function getActionImage(item) {
    const action = {
        type: item.system.actionType.value,
        cnt: item.system.actions.value,
    };
    if (action.type === "action") {
        if (action.cnt === 1) {
            return "systems/pf2e/icons/actions/OneAction.webp";
        } else if (action.cnt === 2) {
            return "systems/pf2e/icons/actions/TwoActions.webp";
        } else if (action.cnt === 3) {
            return "systems/pf2e/icons/actions/ThreeActions.webp";
        }
    } else if (action.type === "reaction") {
        return "systems/pf2e/icons/actions/Reaction.webp";
    } else if (action.type === "free") {
        return "systems/pf2e/icons/actions/FreeAction.webp";
    }

    return item.img;
}

sources.activate:
export const marker = "[X]";

/**
 * Activates an action
 * @param {object} action The action to activate
 * @returns {object} The activated action
 */
export function activateAction(action) {
    setModuleFlag(action, "enabled", true);
    action.name = action.name.replaceAll(marker, "").trim();
    return action;
}

/**
 * Deactivates an action
 * @param {object} action The action to deactivate
 * @returns {object} The deactivated action
 */
export function deactivateAction(action) {
    setModuleFlag(action, "enabled", false);
    action.name = marker.concat(" ", action.name.replaceAll(marker, "").trim());
    return action;
}

/**
 * Turns on or off activations for a particular item
