sluggify:
var jt = String.raw`[\p{Alphabetic}\p{Mark}\p{Decimal_Number}\p{Join_Control}]`, Mt = String.raw`[^\p{Alphabetic}\p{Mark}\p{Decimal_Number}\p{Join_Control}]`, Nt = String.raw`(?=^|$|${jt})`, Pt = String.raw`\p{Lowercase_Letter}`, Ft = String.raw`\p{Uppercase_Letter}`, It = new RegExp(Mt, `gu`), Lt = RegExp(`(${Pt})(${Ft}${Nt})`, `gu`), Rt = /[^-\p{White_Space}\p{Alphabetic}\p{Mark}\p{Decimal_Number}\p{Join_Control}]/gu, zt = RegExp(`${Ft}|${Mt}${Pt}`, `gu`);
function sluggify(e, { camel: t = null } = {}) {
	if (typeof e != `string`) return console.warn("Non-string argument passed to `sluggify`"), ``;
	if (e === `-`) return e;
	switch (t) {
		case null: return e.replace(Lt, `$1-$2`).toLowerCase().replace(/['’]/g, ``).replace(It, ` `).trim().replace(/[-\s]+/g, `-`);
		case `bactrian`: {
			let t = sluggify(e, { camel: `dromedary` });
			return t.charAt(0).toUpperCase() + t.slice(1);
		}
		case `dromedary`: return e.replace(Rt, ``).replace(/[-_]+/g, ` `).replace(zt, (e, t) => t === 0 ? e.toLowerCase() : e.toUpperCase()).replace(/\s+/g, ``);
		default: throw ErrorPF2e(`I don't think that's a real camel.`);
	}
}
